"""Fill text to a line width: greedy word wrap that keeps paragraphs apart."""


def _paragraphs(text):
    """Split text into paragraphs, where a paragraph is a run of lines that are not blank."""
    paragraphs, current = [], []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            paragraphs.append(current)
            current = []
    if current:
        paragraphs.append(current)
    return paragraphs


def _fill(words, width):
    """Greedily pack words into lines of at most width characters. A word longer than width gets its own line."""
    lines, line = [], ""
    for word in words:
        if len(word) > width:
            if line:
                lines.append(line)
            lines.append(word)
            line = ""
        elif not line:
            line = word
        elif len(line) + 1 + len(word) <= width:
            line += " " + word
        else:
            lines.append(line)
            line = word
    if line:
        lines.append(line)
    return lines


def wrap(text, width):
    """Wrap text to width characters. Paragraphs are separated by one empty line. Raises ValueError if width < 1."""
    if width < 1:
        raise ValueError(f"width must be at least 1: {width}")
    out = []
    for paragraph in _paragraphs(text):
        if out:
            out.append("")
        out.extend(_fill(" ".join(paragraph).split(), width))
    return "\n".join(out)

