import contextlib
import io
import unittest

from textkit.cli import main
from textkit.wrap import wrap


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class WrapTest(unittest.TestCase):
    def test_fills_greedily(self):
        self.assertEqual(wrap("aaa bbb ccc", 7), "aaa bbb\nccc")
        self.assertEqual(wrap("aaa bbb ccc", 11), "aaa bbb ccc")
        self.assertEqual(wrap("aaa bbb ccc", 10), "aaa bbb\nccc")

    def test_line_never_exceeds_width(self):
        text = "the quick brown fox jumps over the lazy dog again and again"
        for width in range(1, 30):
            with self.subTest(width=width):
                for line in wrap(text, width).split("\n"):
                    self.assertLessEqual(len(line), width)

    def test_whitespace_collapses_inside_a_paragraph(self):
        self.assertEqual(wrap("a  b\n\tc\r\n d", 10), "a b c d")

    def test_paragraphs_are_separated_by_one_empty_line(self):
        self.assertEqual(wrap("one two\nthree\n\nfour", 9), "one two\nthree\n\nfour")

    def test_several_blank_lines_become_one(self):
        self.assertEqual(wrap("one\n\n\n\ntwo", 10), "one\n\ntwo")

    def test_blank_lines_with_whitespace_count_as_blank(self):
        self.assertEqual(wrap("one\n   \n\t\ntwo", 10), "one\n\ntwo")

    def test_no_leading_or_trailing_blank_lines(self):
        self.assertEqual(wrap("\n\n  one two \n\n\n", 10), "one two")

    def test_empty_and_blank_text(self):
        self.assertEqual(wrap("", 10), "")
        self.assertEqual(wrap(" \n \n", 10), "")

    def test_long_word_goes_on_its_own_line_unbroken(self):
        self.assertEqual(wrap("a abcdefghijkl b", 5), "a\nabcdefghijkl\nb")

    def test_word_exactly_width_fits(self):
        self.assertEqual(wrap("abcde fg", 5), "abcde\nfg")

    def test_hyphenated_words_are_not_split(self):
        self.assertEqual(wrap("well-known state-of-the-art", 10), "well-known\nstate-of-the-art")

    def test_width_below_one_raises(self):
        for width in (0, -1):
            with self.subTest(width=width):
                with self.assertRaises(ValueError):
                    wrap("abc", width)

    def test_width_checked_even_for_empty_text(self):
        with self.assertRaises(ValueError):
            wrap("", 0)

    def test_width_one(self):
        self.assertEqual(wrap("a b cc", 1), "a\nb\ncc")


class WrapCommandTest(unittest.TestCase):
    def test_prints_wrapped_lines(self):
        self.assertEqual(run("wrap", "aaa bbb ccc", "--width", "7"), (0, "aaa bbb\nccc\n", ""))

    def test_default_width_is_40(self):
        text = "x" * 30 + " " + "y" * 9 + " z"
        self.assertEqual(run("wrap", text), (0, "x" * 30 + "\n" + "y" * 9 + " z\n", ""))

    def test_paragraphs_are_printed(self):
        self.assertEqual(run("wrap", "a\n\nb", "--width", "5"), (0, "a\n\nb\n", ""))

    def test_width_zero_exits_2(self):
        code, out, err = run("wrap", "x", "--width", "0")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

    def test_json_output(self):
        code, out, _ = run("--json", "wrap", "aaa bbb ccc", "--width", "7")
        self.assertEqual(code, 0)
        self.assertIn('"output": ["aaa bbb", "ccc"]', out)

    def test_listed_in_commands(self):
        code, out, _ = run("commands")
        self.assertEqual(code, 0)
        self.assertIn("wrap", out.split())


if __name__ == "__main__":
    unittest.main()

